INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Hardware > Auswahl und Komponenten > Zentralelemente > Prozessoren
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann ein Prozessor unabhängig vom Mainboard-Sockel ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Sockel muss kompatibel sein"}, {"text": "Ja", "correct": false, "because": "Inkompatibilität verhindert Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Auswahl eines Prozessors immer die Kühlungsanforderungen berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Überhitzung kann Schäden verursachen"}, {"text": "Nein", "correct": false, "because": "Kühlung ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Leistung eines Prozessors ausschließlich von der Taktfrequenz abhängig?', 2, '[{"text": "Nein", "correct": true, "because": "Kerne und Cache beeinflussen ebenfalls"}, {"text": "Ja", "correct": false, "because": "Taktfrequenz ist nur ein Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Prozessoren ohne Rücksicht auf die Softwareanforderungen ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Software definiert Leistungsbedarf"}, {"text": "Ja", "correct": false, "because": "Leistung muss Anforderungen entsprechen"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Prozessor mit mehr Kernen immer leistungsstärker als einer mit weniger Kernen?', 2, '[{"text": "Nein", "correct": true, "because": "Taktfrequenz und Architektur sind entscheidend"}, {"text": "Ja", "correct": false, "because": "Kerne allein reichen nicht"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium ist bei der Auswahl eines Prozessors am wichtigsten?', 3, '[{"text": "Anwendungsanforderungen", "correct": true, "because": "Bestimmen Leistungsbedarf"}, {"text": "Preis", "correct": false, "because": "Wichtig, aber sekundär"}, {"text": "Marke", "correct": false, "because": "Persönliche Präferenz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einheit wird primär zur Messung der Prozessorleistung verwendet?', 2, '[{"text": "GHz", "correct": true, "because": "Taktfrequenz ist Standardmaß"}, {"text": "Watt", "correct": false, "because": "Leistungsaufnahme"}, {"text": "GB", "correct": false, "because": "Speichergröße"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor bestimmt die Kompatibilität eines Prozessors mit dem Mainboard?', 2, '[{"text": "Sockeltyp", "correct": true, "because": "Physische und elektrische Verbindung"}, {"text": "Taktfrequenz", "correct": false, "because": "Leistung, nicht Kompatibilität"}, {"text": "Anzahl der Kerne", "correct": false, "because": "Unabhängig vom Sockel"}]'),
('00000000-0000-0000-0000-000000000000', 'Was erhöht die Multitasking-Fähigkeit eines Prozessors?', 3, '[{"text": "Anzahl der Kerne", "correct": true, "because": "Mehr Kerne, mehr parallele Aufgaben"}, {"text": "Größe des Lüfters", "correct": false, "because": "Kühlung, nicht Multitasking"}, {"text": "Spannungsversorgung", "correct": false, "because": "Unterstützend, nicht direkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prozessorarchitektur ist für Workstations oft bevorzugt?', 2, '[{"text": "x86-64", "correct": true, "because": "Weit verbreitet und leistungsstark"}, {"text": "RISC", "correct": false, "because": "Eher in Spezialsystemen"}, {"text": "ARM", "correct": false, "because": "Für Mobilgeräte"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften beeinflussen die Leistung eines Prozessors?', 4, '[{"text": "Taktfrequenz", "correct": true, "because": "Geschwindigkeit pro Zyklus"}, {"text": "Anzahl der Kerne", "correct": true, "because": "Parallele Verarbeitung"}, {"text": "Cache-Größe", "correct": true, "because": "Schneller Datenzugriff"}, {"text": "Farbe des Chips", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren müssen bei der Auswahl eines Prozessors berücksichtigt werden?', 3, '[{"text": "Softwareanforderungen", "correct": true, "because": "Bestimmen Leistungsbedarf"}, {"text": "Mainboard-Kompatibilität", "correct": true, "because": "Sockel und Chipsatz"}, {"text": "Kühlung", "correct": true, "because": "Verhindert Überhitzung"}, {"text": "Gehäusegröße", "correct": false, "because": "Indirekt relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prozessor-Features sind für grafikintensive Anwendungen wichtig?', 3, '[{"text": "Hohe Taktfrequenz", "correct": true, "because": "Schnelle Berechnungen"}, {"text": "Viele Kerne", "correct": true, "because": "Parallele Aufgaben"}, {"text": "Großer Cache", "correct": true, "because": "Schneller Zugriff"}, {"text": "Integrierte Grafik", "correct": false, "because": "Dedizierte GPU oft nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Prozessorauswahl auftreten?', 4, '[{"text": "Inkompatibilität mit Mainboard", "correct": true, "because": "Sockel passt nicht"}, {"text": "Unzureichende Kühlung", "correct": true, "because": "Überhitzung möglich"}, {"text": "Überschreitung des Budgets", "correct": true, "because": "Kostenfaktor"}, {"text": "Falsche Farbe", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen einen Prozessor zukunftssicher?', 3, '[{"text": "Hohe Kernanzahl", "correct": true, "because": "Für Multitasking"}, {"text": "Unterstützung aktueller Standards", "correct": true, "because": "Kompatibilität"}, {"text": "Energieeffizienz", "correct": true, "because": "Reduziert Betriebskosten"}, {"text": "Integrierter Lüfter", "correct": false, "because": "Nicht immer enthalten"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Taktfrequenz eines Prozessors wird in GHz gemessen. b) Mehr Kerne garantieren immer bessere Leistung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "GHz ja, Kerne abhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Prozessor-Sockel muss zum Mainboard passen. b) Kühlung ist bei Prozessoren optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sockel ja, Kühlung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Prozessor mit größerem Cache ist schneller. b) Die Leistung hängt nur von der Anzahl der Kerne ab.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Cache ja, Leistung multifaktoriell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Softwareanforderungen beeinflussen die Prozessorauswahl. b) Ein Prozessor mit 2 GHz ist immer langsamer als einer mit 3 GHz.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Software ja, GHz nicht allein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Prozessoren mit mehr Kernen eignen sich für Multitasking. b) Die Wahl des Prozessors ist unabhängig vom Mainboard.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Multitasking ja, Mainboard relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

